"use client"

import { useId, useState } from "react"
import { motion } from "motion/react"

import { Button } from "@/components/ui/button"
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs"
import { formatChartNumber } from "@/lib/chart-format"
import { extentWithZero, scaleLinear } from "@/lib/chart-geom"
import {
  ChartCard,
  ChartInsight,
  ChartKpi,
  ChartLegend,
  ChartTip,
  chartStatusLabels,
  chartStatusLabelsEs,
  chartTransition,
  usePlotBox,
  usePrefersReducedMotion,
  type ChartCardClassNames,
  type ChartStatus,
  type ChartStatusLabels,
} from "@/components/ui/chart-card"
import { SeriesPatterns, seriesPaint } from "@/components/ui/chart-marks"

export type StackedSeries = { id: string; label: string }
export type StackedPoint = { key: string; label: string; axisLabel?: string; values: Record<string, number> }
export type StackedPeriod = { id: string; label: string; points: StackedPoint[] }
export type StackedNote = { title: string; body: string; actionLabel?: string; onAction?: () => void }

export type StackedColumnsLabels = ChartStatusLabels & {
  period: string
  legend: string
  total: string
  column: (label: string, value: string) => string
}

export const stackedColumnsLabels: StackedColumnsLabels = {
  ...chartStatusLabels,
  period: "Range",
  legend: "Series",
  total: "Total",
  column: (label, value) => `${label}: ${value}`,
}

export const stackedColumnsLabelsEs: StackedColumnsLabels = {
  ...chartStatusLabelsEs,
  period: "Rango",
  legend: "Series",
  total: "Total",
  column: (label, value) => `${label}: ${value}`,
}

export type StackedColumnsProps = {
  title: string
  description?: string
  series: StackedSeries[]
  periods: StackedPeriod[]
  periodId?: string
  onPeriodChange?: (id: string) => void
  activeKey?: string | null
  onActiveChange?: (key: string | null) => void
  note?: StackedNote
  locale?: string
  suffix?: string
  status?: ChartStatus
  labels?: Partial<StackedColumnsLabels>
  onMenu?: () => void
  onRetry?: () => void
  height?: number
  className?: string
  classNames?: ChartCardClassNames
}

function pointTotal(point: StackedPoint, series: StackedSeries[]) {
  return series.reduce((sum, item) => sum + (point.values[item.id] ?? 0), 0)
}

export function StackedColumns({
  title,
  description,
  series,
  periods,
  periodId,
  onPeriodChange,
  activeKey,
  onActiveChange,
  note,
  locale,
  suffix,
  status = "ready",
  labels,
  onMenu,
  onRetry,
  height = 200,
  className,
  classNames,
}: StackedColumnsProps) {
  const copy = { ...stackedColumnsLabels, ...labels }
  const pattern = useId().replace(/:/g, "")
  const reduced = usePrefersReducedMotion()
  const { node: plotNode, width } = usePlotBox(320, height)
  const [internalPeriod, setPeriod] = useState(periods[0]?.id ?? "")
  const [internalKey, setKey] = useState<string | null>(null)
  const [seriesId, setSeriesId] = useState<string | null>(null)
  const currentId = periodId ?? internalPeriod
  const period = periods.find((item) => item.id === currentId) ?? periods[0]
  const points = period?.points ?? []
  const active = activeKey !== undefined ? activeKey : internalKey
  const empty = points.length === 0 || series.length === 0
  const view = status !== "ready" ? status : empty ? "empty" : "ready"
  const stacks = points.map((point) => {
    let up = 0
    let down = 0
    for (const item of series) {
      const value = point.values[item.id] ?? 0
      if (value >= 0) up += value
      else down += value
    }
    return { up, down }
  })
  const domain = extentWithZero(stacks.flatMap((stack) => [stack.up, stack.down]))
  const base = scaleLinear(0, domain.min, domain.max, height - 24, 12)
  const slot = Math.max(1, (width - 16) / Math.max(1, points.length))
  const barWidth = Math.max(6, Math.min(22, slot * 0.55))
  const focus = points.find((point) => point.key === active) ?? null
  const kpiPoints = focus ? [focus] : points
  const withUnit = (value: number) => formatChartNumber(value, locale) + (suffix ? ` ${suffix}` : "")

  function choosePeriod(id: string) {
    if (periodId === undefined) setPeriod(id)
    onPeriodChange?.(id)
    if (activeKey === undefined) setKey(null)
    onActiveChange?.(null)
  }

  function chooseKey(key: string | null) {
    if (activeKey === undefined) setKey(key)
    onActiveChange?.(key)
  }

  return (
    <ChartCard
      title={title}
      description={description}
      status={view}
      labels={copy}
      onMenu={onMenu}
      onRetry={onRetry}
      className={className}
      classNames={classNames}
      summary={points.map((point) => copy.column(point.label, withUnit(pointTotal(point, series)))).join(", ")}
      columns={series.map((item) => ({ id: item.id, label: item.label }))}
      rows={points.map((point) => ({
        id: point.key,
        label: point.label,
        cells: Object.fromEntries(series.map((item) => [item.id, formatChartNumber(point.values[item.id] ?? 0, locale)])),
      }))}
      live={focus ? copy.column(focus.label, withUnit(pointTotal(focus, series))) : undefined}
      kpis={
        <>
          {series.slice(0, 2).map((item) => (
            <ChartKpi
              key={item.id}
              label={item.label}
              value={withUnit(kpiPoints.reduce((sum, point) => sum + (point.values[item.id] ?? 0), 0))}
              hint={focus?.label}
            />
          ))}
        </>
      }
      controls={
        periods.length > 1 ? (
          <Tabs value={currentId} onValueChange={choosePeriod}>
            <TabsList aria-label={copy.period}>
              {periods.map((item) => (
                <TabsTrigger key={item.id} value={item.id}>
                  {item.label}
                </TabsTrigger>
              ))}
            </TabsList>
          </Tabs>
        ) : null
      }
      legend={
        <ChartLegend
          label={copy.legend}
          activeId={seriesId}
          onActiveChange={setSeriesId}
          items={series.map((item, index) => ({ id: item.id, label: item.label, tone: index }))}
        />
      }
      insight={
        note ? (
          <ChartInsight
            title={note.title}
            body={note.body}
            action={
              note.actionLabel ? (
                <Button type="button" size="sm" variant="outline" onClick={note.onAction}>
                  {note.actionLabel}
                </Button>
              ) : null
            }
          />
        ) : null
      }
    >
      <div
        ref={plotNode}
        className="relative w-full overflow-x-auto"
        style={{ height }}
        role="slider"
        tabIndex={0}
        aria-label={title}
        aria-valuemin={1}
        aria-valuemax={Math.max(1, points.length)}
        aria-valuenow={Math.max(1, (focus ? points.findIndex((point) => point.key === focus.key) : points.length - 1) + 1)}
        aria-valuetext={focus ? copy.column(focus.label, withUnit(pointTotal(focus, series))) : copy.total}
        onKeyDown={(event) => {
          if (!points.length || !["ArrowRight", "ArrowLeft", "Home", "End", "Escape"].includes(event.key)) return
          event.preventDefault()
          if (event.key === "Escape") {
            chooseKey(null)
            return
          }
          const index = Math.max(0, points.findIndex((point) => point.key === active))
          const next = event.key === "Home" ? 0 : event.key === "End" ? points.length - 1 : event.key === "ArrowRight" ? Math.min(points.length - 1, index + 1) : Math.max(0, index - 1)
          chooseKey(points[next]?.key ?? null)
        }}
      >
        <svg width={Math.max(width, points.length * 28)} height={height} className="block">
          <SeriesPatterns id={pattern} />
          <line x1={0} x2={Math.max(width, points.length * 28)} y1={base} y2={base} className="stroke-border" strokeDasharray="3 4" />
          {points.map((point, index) => {
            const x = 12 + index * slot + (slot - barWidth) / 2
            let up = base
            let down = base
            const hot = active === point.key
            return (
              <g key={`${currentId}-${point.key}`} data-slot="stacked-column" onMouseEnter={() => chooseKey(point.key)} opacity={!active || hot ? 1 : 0.4}>
                {series.map((item, seriesIndex) => {
                  const value = point.values[item.id] ?? 0
                  const y = scaleLinear(value, domain.min, domain.max, height - 24, 12)
                  const bar = value >= 0 ? base - y : y - base
                  const top = value >= 0 ? up - bar : down
                  if (value >= 0) up -= bar
                  else down += bar
                  return (
                    <motion.rect
                      key={item.id}
                      x={x}
                      width={barWidth}
                      rx={2}
                      initial={reduced ? false : { height: 0, y: base }}
                      animate={{ height: Math.max(0, bar), y: top }}
                      transition={chartTransition(reduced)}
                      fill={seriesPaint(pattern, seriesIndex)}
                      opacity={!seriesId || seriesId === item.id ? 1 : 0.2}
                    />
                  )
                })}
                <text x={x + barWidth / 2} y={height - 6} textAnchor="middle" className={hot ? "fill-foreground text-[10px] font-medium" : "fill-muted-foreground text-[10px]"}>
                  {point.axisLabel ?? point.label}
                </text>
              </g>
            )
          })}
        </svg>
        <ChartTip open={focus != null} x={12 + Math.max(0, points.findIndex((point) => point.key === active)) * slot + slot / 2} y={24}>
          {focus ? (
            <span>
              {focus.label}
              {series.map((item) => (
                <span key={item.id} className="mt-0.5 block">
                  {item.label}: {withUnit(focus.values[item.id] ?? 0)}
                </span>
              ))}
            </span>
          ) : null}
        </ChartTip>
      </div>
    </ChartCard>
  )
}

"use client"

import { useId, useLayoutEffect, useRef, useState, useSyncExternalStore, type KeyboardEvent, type ReactNode } from "react"
import { CircleAlert, MoreHorizontal } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Card } from "@/components/ui/card"
import { cn } from "@/lib/utils"
import { motionPresets } from "@/lib/motion"
import { SeriesSwatch } from "@/components/ui/chart-marks"

const REDUCE_QUERY = "(prefers-reduced-motion: reduce)"

function subscribeReduced(onStoreChange: () => void) {
  const media = window.matchMedia(REDUCE_QUERY)
  media.addEventListener("change", onStoreChange)
  return () => media.removeEventListener("change", onStoreChange)
}

export function usePrefersReducedMotion() {
  return useSyncExternalStore(subscribeReduced, () => window.matchMedia(REDUCE_QUERY).matches, () => false)
}

export function chartTransition(reduced: boolean) {
  if (reduced) return { duration: 0 }
  return { duration: motionPresets.duration.considered, ease: [...motionPresets.ease.enter] as [number, number, number, number] }
}

export type ChartStatus = "ready" | "loading" | "empty" | "error"

export type ChartStatusLabels = {
  loading: string
  empty: string
  error: string
  retry: string
  more: string
}

export const chartStatusLabels: ChartStatusLabels = {
  loading: "Loading",
  empty: "Nothing to show yet",
  error: "Could not load this chart",
  retry: "Try again",
  more: "More",
}

export const chartStatusLabelsEs: ChartStatusLabels = {
  loading: "Cargando",
  empty: "Todavía no hay datos",
  error: "No se pudo cargar el gráfico",
  retry: "Reintentar",
  more: "Más",
}

export type ChartSummaryColumn = { id: string; label: string }
export type ChartSummaryRow = { id: string; label: string; cells: Record<string, string> }

export type ChartCardClassNames = {
  root?: string
  header?: string
  title?: string
  description?: string
  kpis?: string
  controls?: string
  body?: string
  legend?: string
  insight?: string
  footer?: string
}

export type ChartCardProps = {
  title: string
  description?: string
  status?: ChartStatus
  labels?: Partial<ChartStatusLabels>
  onRetry?: () => void
  menuLabel?: string
  onMenu?: () => void
  menu?: ReactNode
  kpis?: ReactNode
  controls?: ReactNode
  legend?: ReactNode
  insight?: ReactNode
  footer?: ReactNode
  /** One-sentence description of the data, read with the chart. */
  summary: string
  tableCaption?: string
  columns?: ChartSummaryColumn[]
  rows?: ChartSummaryRow[]
  live?: string
  children?: ReactNode
  className?: string
  classNames?: ChartCardClassNames
}

export function ChartCard({
  title,
  description,
  status = "ready",
  labels,
  onRetry,
  menuLabel,
  onMenu,
  menu,
  kpis,
  controls,
  legend,
  insight,
  footer,
  summary,
  tableCaption,
  columns,
  rows,
  live,
  children,
  className,
  classNames,
}: ChartCardProps) {
  const uid = useId().replace(/:/g, "")
  const titleId = `${uid}-title`
  const summaryId = `${uid}-summary`
  const copy = { ...chartStatusLabels, ...labels }
  const root = `[data-chart-card="${uid}"]`

  return (
    <Card
      data-slot="chart-card"
      data-chart-card={uid}
      data-status={status}
      aria-labelledby={titleId}
      aria-describedby={summaryId}
      className={cn("w-full min-w-0 gap-3 rounded-2xl py-4 shadow-sm ring-foreground/10", classNames?.root, className)}
    >
      <style>{`
        @media (prefers-reduced-motion: reduce) {
          ${root}, ${root} * {
            animation: none !important;
            transition: none !important;
          }
        }
      `}</style>
      <header className={cn("flex items-start gap-3 px-4", classNames?.header)}>
        <div className="min-w-0 flex-1">
          <h2 id={titleId} data-slot="chart-card-title" className={cn("truncate text-base font-medium leading-snug", classNames?.title)}>
            {title}
          </h2>
          {description ? (
            <p className={cn("mt-0.5 text-xs text-muted-foreground", classNames?.description)}>{description}</p>
          ) : null}
        </div>
        {menu ??
          (onMenu ? (
            <Button type="button" variant="ghost" size="icon-xs" aria-label={menuLabel ?? copy.more} onClick={onMenu}>
              <MoreHorizontal />
            </Button>
          ) : null)}
      </header>
      {kpis ? <div className={cn("grid grid-cols-2 gap-3 px-4 sm:grid-cols-3", classNames?.kpis)}>{kpis}</div> : null}
      {controls ? <div className={cn("px-4", classNames?.controls)}>{controls}</div> : null}
      <div className={cn("min-w-0 px-4", classNames?.body)}>
        {status === "ready" ? (
          children
        ) : (
          <ChartState status={status} label={copy[status]} onRetry={status === "error" ? onRetry : undefined} retryLabel={copy.retry} />
        )}
      </div>
      {status === "ready" && legend ? <div className={cn("px-4", classNames?.legend)}>{legend}</div> : null}
      {status === "ready" && insight ? <div className={cn("px-4", classNames?.insight)}>{insight}</div> : null}
      {status === "ready" && footer ? <div className={cn("flex flex-wrap items-center gap-2 px-4", classNames?.footer)}>{footer}</div> : null}
      <p id={summaryId} className="sr-only">
        {summary}
      </p>
      {live ? (
        <p className="sr-only" aria-live="polite" aria-atomic="true" data-slot="chart-live">
          {live}
        </p>
      ) : null}
      {columns && rows && rows.length > 0 ? (
        <table className="sr-only">
          {tableCaption ? <caption>{tableCaption}</caption> : null}
          <thead>
            <tr>
              <th scope="col">{tableCaption ?? title}</th>
              {columns.map((column) => (
                <th key={column.id} scope="col">
                  {column.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.id}>
                <th scope="row">{row.label}</th>
                {columns.map((column) => (
                  <td key={column.id}>{row.cells[column.id] ?? ""}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      ) : null}
    </Card>
  )
}

export function ChartState({
  status,
  label,
  onRetry,
  retryLabel,
}: {
  status: Exclude<ChartStatus, "ready">
  label: string
  onRetry?: () => void
  retryLabel: string
}) {
  return (
    <div
      data-slot="chart-state"
      data-status={status}
      className="flex min-h-36 flex-col items-center justify-center gap-3 rounded-xl border border-dashed px-4 py-6 text-center"
      role={status === "error" ? "alert" : "status"}
    >
      {status === "loading" ? (
        <div className="flex h-16 items-end gap-1.5" aria-hidden>
          {[40, 70, 52, 88, 60].map((height) => (
            <span key={height} className="w-3 rounded-sm bg-muted motion-safe:animate-pulse" style={{ height }} />
          ))}
        </div>
      ) : null}
      {status === "error" ? <CircleAlert className="size-5 text-destructive" aria-hidden /> : null}
      <p className="max-w-sm text-sm text-muted-foreground">{label}</p>
      {onRetry ? (
        <Button type="button" size="sm" variant="outline" onClick={onRetry}>
          {retryLabel}
        </Button>
      ) : null}
    </div>
  )
}

export function ChartKpi({ label, value, hint }: { label: string; value: string; hint?: string }) {
  return (
    <div data-slot="chart-kpi" className="min-w-0">
      <p className="truncate text-xs text-muted-foreground">{label}</p>
      <p className="truncate text-xl font-semibold tracking-tight tabular-nums">{value}</p>
      {hint ? <p className="truncate text-xs text-muted-foreground">{hint}</p> : null}
    </div>
  )
}

export function ChartInsight({
  title,
  body,
  action,
}: {
  title: string
  body: string
  action?: ReactNode
}) {
  return (
    <div data-slot="chart-insight" className="flex items-start gap-3 rounded-xl bg-muted/70 p-3">
      <div className="min-w-0 flex-1">
        <p className="text-sm font-medium">{title}</p>
        <p className="text-sm text-muted-foreground">{body}</p>
      </div>
      {action}
    </div>
  )
}

export type ChartLegendItem = {
  id: string
  label: string
  value?: string
  tone: number
}

export function ChartLegend({
  label,
  items,
  activeId,
  onActiveChange,
}: {
  label: string
  items: ChartLegendItem[]
  activeId?: string | null
  onActiveChange?: (id: string | null) => void
}) {
  const [focus, setFocus] = useState(0)
  const refs = useRef<Array<HTMLButtonElement | null>>([])

  function select(index: number) {
    const item = items[index]
    if (!item) return
    setFocus(index)
    refs.current[index]?.focus()
    onActiveChange?.(activeId === item.id ? null : item.id)
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (!items.length) return
    const keys = ["ArrowRight", "ArrowLeft", "ArrowUp", "ArrowDown", "Home", "End"]
    if (!keys.includes(event.key)) return
    event.preventDefault()
    const next =
      event.key === "Home" ? 0 : event.key === "End" ? items.length - 1 : event.key === "ArrowRight" || event.key === "ArrowDown" ? (focus + 1) % items.length : (focus - 1 + items.length) % items.length
    select(next)
  }

  return (
    <div role="toolbar" aria-label={label} data-slot="chart-legend" className="flex flex-wrap gap-2" onKeyDown={onKeyDown}>
      {items.map((item, index) => {
        const pressed = activeId === item.id
        return (
          <button
            key={item.id}
            ref={(node) => {
              refs.current[index] = node
            }}
            type="button"
            data-slot="chart-legend-item"
            aria-pressed={pressed}
            tabIndex={index === focus ? 0 : -1}
            className={cn(
              "inline-flex max-w-full min-w-0 items-center gap-1.5 rounded-full px-2 py-1 text-xs outline-none focus-visible:ring-2 focus-visible:ring-ring",
              pressed ? "bg-muted ring-1 ring-foreground/20" : "hover:bg-muted/70",
            )}
            onClick={() => select(index)}
          >
            <SeriesSwatch index={item.tone} />
            <span className="truncate">{item.label}</span>
            {item.value ? <span className="font-medium tabular-nums text-foreground">{item.value}</span> : null}
          </button>
        )
      })}
    </div>
  )
}

export function ChartTip({
  open,
  x,
  y,
  children,
}: {
  open: boolean
  x: number | string
  y: number | string
  children: ReactNode
}) {
  if (!open) return null
  return (
    <div
      data-slot="chart-tip"
      role="tooltip"
      className="pointer-events-none absolute z-10 max-w-[14rem] rounded-lg bg-foreground px-2.5 py-1.5 text-xs text-background shadow-md"
      style={{ left: x, top: y, transform: "translate(-50%, -110%)" }}
    >
      {children}
    </div>
  )
}

/** Measured plot width. `node` is the element ref; read `node.current` only in effects and events. */
export function usePlotBox(fallbackWidth = 320, fallbackHeight = 180) {
  const node = useRef<HTMLDivElement>(null)
  const [width, setWidth] = useState(fallbackWidth)
  useLayoutEffect(() => {
    const element = node.current
    if (!element) return
    const read = () => {
      const next = element.clientWidth
      if (next > 0) setWidth(next)
    }
    read()
    const observer = new ResizeObserver(read)
    observer.observe(element)
    return () => observer.disconnect()
  }, [fallbackHeight])
  return { node, width }
}

export function dimOpacity(active: boolean) {
  return active ? 1 : 0.18
}

import { seriesColor, seriesMark, seriesPatternId } from "@/lib/chart-series"
import { cn } from "@/lib/utils"

const MARKS = [0, 1, 2, 3, 4]

/** SVG patterns. Each series pairs a chart token with a distinct mark. */
export function SeriesPatterns({ id }: { id: string }) {
  return (
    <defs>
      {MARKS.map((mark) => (
        <pattern key={mark} id={`${id}-mark-${mark}`} width="6" height="6" patternUnits="userSpaceOnUse">
          <rect width="6" height="6" fill={`var(--chart-${mark + 1})`} />
          {mark === 1 ? <path d="M0 6 L6 0" stroke="var(--foreground)" strokeOpacity="0.55" /> : null}
          {mark === 2 ? <circle cx="2" cy="2" r="1" fill="var(--foreground)" fillOpacity="0.55" /> : null}
          {mark === 3 ? <path d="M0 3 H6" stroke="var(--foreground)" strokeOpacity="0.5" /> : null}
          {mark === 4 ? <path d="M0 6 L6 0 M0 0 L6 6" stroke="var(--foreground)" strokeOpacity="0.45" /> : null}
        </pattern>
      ))}
    </defs>
  )
}

export function seriesPaint(prefix: string, index: number) {
  return `url(#${seriesPatternId(prefix, index)})`
}

export function SeriesSwatch({ index, className }: { index: number; className?: string }) {
  const mark = seriesMark(index)
  const image =
    mark === 1
      ? "repeating-linear-gradient(45deg, transparent, transparent 2px, var(--foreground) 2px, var(--foreground) 3px)"
      : mark === 2
        ? "radial-gradient(circle at 30% 30%, var(--foreground) 0.8px, transparent 1px)"
        : mark === 3
          ? "repeating-linear-gradient(0deg, transparent, transparent 2px, var(--foreground) 2px, var(--foreground) 3px)"
          : mark === 4
            ? "repeating-linear-gradient(45deg, transparent, transparent 2px, var(--foreground) 2px, var(--foreground) 3px), repeating-linear-gradient(-45deg, transparent, transparent 2px, var(--foreground) 2px, var(--foreground) 3px)"
            : undefined
  return (
    <span
      aria-hidden
      data-slot="chart-swatch"
      data-mark={mark}
      className={cn("inline-block size-2.5 shrink-0 rounded-[3px] ring-1 ring-foreground/15", className)}
      style={{ backgroundColor: seriesColor(index), backgroundImage: image }}
    />
  )
}

export type ChartLocale = string

const numberFormat = new Map<string, Intl.NumberFormat>()
const percentFormat = new Map<string, Intl.NumberFormat>()
const currencyFormat = new Map<string, Intl.NumberFormat>()

function cached(map: Map<string, Intl.NumberFormat>, key: string, create: () => Intl.NumberFormat) {
  let format = map.get(key)
  if (!format) {
    format = create()
    map.set(key, format)
  }
  return format
}

/** `es` and `en` map to es-MX and en-US. Any other BCP 47 tag is used as-is. */
export function resolveChartLocale(locale: ChartLocale | undefined): string {
  if (!locale || locale === "en") return "en-US"
  if (locale === "es") return "es-MX"
  return locale
}

export function formatChartNumber(value: number, locale: ChartLocale | undefined, digits = 1): string {
  const safe = Number.isFinite(value) ? value : 0
  const tag = resolveChartLocale(locale)
  const fraction = Number.isInteger(safe) ? 0 : digits
  const format = cached(numberFormat, `${tag}:${fraction}`, () =>
    new Intl.NumberFormat(tag, { maximumFractionDigits: fraction, minimumFractionDigits: 0 }),
  )
  return format.format(safe)
}

/** `share` is a ratio, 0.1 → 10%. */
export function formatChartPercent(share: number, locale: ChartLocale | undefined, digits = 0): string {
  const safe = Number.isFinite(share) ? share : 0
  const tag = resolveChartLocale(locale)
  const format = cached(percentFormat, `${tag}:${digits}`, () =>
    new Intl.NumberFormat(tag, { style: "percent", maximumFractionDigits: digits, minimumFractionDigits: 0 }),
  )
  return format.format(safe)
}

export function formatChartCurrency(value: number, locale: ChartLocale | undefined, currency: string): string {
  const safe = Number.isFinite(value) ? value : 0
  const tag = resolveChartLocale(locale)
  const format = cached(currencyFormat, `${tag}:${currency}`, () =>
    new Intl.NumberFormat(tag, { style: "currency", currency, maximumFractionDigits: 0 }),
  )
  return format.format(safe)
}

export type ChartUnit = {
  id: string
  label: string
  /** Multiplies the raw measure. Defaults to 1. */
  scale?: number
  /** When set, values format as money in this ISO currency. */
  currency?: string
  /** Appended after a plain number, such as "kg". */
  suffix?: string
}

export function formatChartUnit(value: number, unit: ChartUnit | undefined, locale: ChartLocale | undefined): string {
  const scaled = value * (unit?.scale ?? 1)
  if (unit?.currency) return formatChartCurrency(scaled, locale, unit.currency)
  const text = formatChartNumber(scaled, locale)
  return unit?.suffix ? `${text} ${unit.suffix}` : text
}

import { chartVar, type ChartTone } from "@/lib/chart-tone"

/** Host series palette. Charts cycle `--chart-1` … `--chart-5`. */
export const SERIES_COUNT = 5

export function seriesTone(index: number): ChartTone {
  const tone = (Math.abs(index) % SERIES_COUNT) + 1
  return tone as ChartTone
}

export function seriesColor(index: number): string {
  return chartVar(seriesTone(index))
}

/**
 * Non-color cue so a series is not identified by hue alone.
 * 0 solid, 1 diagonal, 2 dots, 3 horizontal, 4 cross.
 */
export function seriesMark(index: number): number {
  return Math.abs(index) % SERIES_COUNT
}

export function seriesPatternId(prefix: string, index: number): string {
  return `${prefix}-mark-${seriesMark(index)}`
}

/** shadcn chart tokens. Hosts define --chart-1 … --chart-5. */
export const CHART_TONES = [1, 2, 3, 4, 5] as const

export type ChartTone = (typeof CHART_TONES)[number]

export function chartVar(tone: ChartTone = 1): string {
  return `var(--chart-${tone})`
}

export function chartBgClass(tone: ChartTone = 1): string {
  switch (tone) {
    case 1:
      return "bg-chart-1"
    case 2:
      return "bg-chart-2"
    case 3:
      return "bg-chart-3"
    case 4:
      return "bg-chart-4"
    case 5:
      return "bg-chart-5"
  }
}

export function chartFillClass(tone: ChartTone = 1): string {
  switch (tone) {
    case 1:
      return "fill-chart-1"
    case 2:
      return "fill-chart-2"
    case 3:
      return "fill-chart-3"
    case 4:
      return "fill-chart-4"
    case 5:
      return "fill-chart-5"
  }
}

